                    { 2, null, "Tenses", "Nắm vững cách sử dụng các thì hiện tại, quá khứ và tương lai trong tiếng Anh.", 2, createdAt },
                    { 3, null, "Sentence Structures", "Học cách xây dựng câu hoàn chỉnh và câu phức bằng cách sử dụng cấu trúc so sánh, câu điều kiện, câu bị động và các mệnh đề.", 3, createdAt },
                    { 4, null, "Question Forms", "Học cách đặt câu hỏi để tìm kiếm thông tin bằng nhiều dạng câu hỏi khác nhau trong tiếng Anh.", 4, createdAt },
                    { 5, null, "Common Structures", "Nắm vững các cấu trúc tiếng Anh thông dụng để diễn đạt ý tưởng, cảm xúc và mối quan hệ giữa các khái niệm.", 5, createdAt },
                    { 6, null, "Advanced Structures", "Các cấu trúc nâng cao từ trình độ CEFR B2 đến C2: động từ khuyết thiếu ở dạng hoàn thành, mạo từ zero, sự hòa hợp giữa chủ ngữ và động từ, cụm động từ, cấu tạo từ, đảo ngữ, câu chẻ, mệnh đề phân từ và các từ/cụm từ liên kết diễn ngôn.", 6, createdAt }
