            migrationBuilder.InsertData(
                table: "grammar_categories",
                columns: new[] { "Id", "parent_id", "Name", "description", "display_order", "created_at" },
                values: new object[,]
                {
                    { 7, 1, "Articles (Mạo từ)", "Chuyên mục \"Articles (Mạo từ)\" cung cấp các quy tắc sử dụng mạo từ nâng cao và chuyên sâu trong tiếng Anh. Bạn sẽ nắm vững cách dùng mạo từ khuyết (Zero article) với danh từ chỉ cơ sở, phương tiện, bữa ăn, thời gian, cũng như cách sử dụng \"The\" với địa danh, công trình và các trường hợp mang tính đại diện. Bên cạnh đó, bài học còn hướng dẫn áp dụng \"a/an\" để chỉ tỷ lệ và trong câu cảm thán, giúp bạn giao tiếp tự nhiên và chuẩn xác hơn.", 1, createdAt },
                    { 8, 1, "Pronouns (Đại từ)", "Nhóm bài học này sẽ giúp bạn làm chủ các dạng đại từ nâng cao để diễn đạt chuẩn xác và linh hoạt hơn. Bạn sẽ phân biệt rõ ràng giữa đại từ sở hữu và tính từ sở hữu, đồng thời nắm vững quy tắc hòa hợp đại từ trong các trường hợp phức tạp như everyone , each , neither hay chủ ngữ ghép. Bên cạnh đó, các bài học cũng đi sâu vào cách sử dụng đại từ phản thân và đại từ nhấn mạnh để tạo điểm nhấn tự nhiên cho câu văn.", 2, createdAt },
                    { 9, 1, "Adjectives (Tính từ)", "Nhóm bài học \"Adjectives\" giúp bạn nâng cấp kỹ năng diễn đạt tiếng Anh thông qua việc sử dụng tính từ một cách chuyên sâu và tự nhiên. Bạn sẽ nắm vững phân loại tính từ theo cấp độ, cách điều chỉnh sắc thái bằng các từ nhấn mạnh hay làm giảm mức độ, cùng vị trí chuẩn xác của tính từ trong câu. Đặc biệt, quy tắc sắp xếp thứ tự nhiều tính từ cùng lúc sẽ giúp câu văn của bạn trở nên mạch lạc, mượt mà và đúng ngữ pháp hơn.", 3, createdAt },
                    { 10, 1, "Adverbs (Trạng từ)", "Chuyên mục này cung cấp kiến thức nâng cao về trạng từ trong tiếng Anh, giúp bạn nắm vững cách sử dụng và sắp xếp câu từ chính xác, tự nhiên hơn. Bạn sẽ học về vị trí của trạng từ chỉ tần suất, quy tắc sắp xếp thứ tự trạng từ cuối câu, trạng từ chỉ mức độ, cũng như cách phân biệt các dạng trạng từ dễ nhầm lẫn như hard/hardly hay late/lately. Bên cạnh đó, bài học còn mở rộng sang trạng từ quan hệ và các trạng từ chỉ góc nhìn, đánh giá giúp nâng cao toàn diện kỹ năng giao tiếp và viết lách.", 4, createdAt },
                    { 11, 1, "Verbs (Động từ)", "Nhóm bài học này giúp bạn nâng cao kỹ năng sử dụng động từ qua việc làm chủ các cấu trúc động từ đi kèm, phân biệt nội động từ - ngoại động từ và cách dùng động từ có hai tân ngữ. Bên cạnh đó, bạn sẽ hiểu rõ hơn về hệ thống động từ nối (linking verbs) cũng như so sánh chi tiết các động từ khuyết thiếu theo từng ngữ cảnh giao tiếp. Đây là nền tảng quan trọng giúp bạn diễn đạt chính xác, tự nhiên và linh hoạt hơn trong cả văn nói lẫn văn viết.", 5, createdAt },
                    { 12, 1, "Nouns (Danh từ)", "Chuyên mục \"Nouns (Danh từ)\" giúp bạn nâng cao vốn từ và nắm vững các quy tắc ngữ pháp chuyên sâu hơn về danh từ trong tiếng Anh. Bạn sẽ khám phá sự thay đổi nghĩa linh hoạt của danh từ khi ở dạng đếm được và không đếm được, cùng các quy tắc tạo dạng số nhiều đặc biệt. Bên cạnh đó, bài học còn làm rõ cấu trúc của các loại danh từ ghép (viết rời, có dấu gạch nối, viết liền) nhằm hỗ trợ bạn diễn đạt tự nhiên và chính xác nhất.", 6, createdAt },
                    { 13, 1, "Quantifiers & Determiners (Lượng từ và hạn định từ)", "Chuyên đề này sẽ giúp bạn nâng cao kỹ năng diễn đạt số lượng và xác định danh từ một cách chính xác, tự nhiên trong tiếng Anh. Bạn sẽ nắm vững sự khác biệt chi tiết giữa các lượng từ thông dụng, bao gồm cả sắc thái tích cực hay tiêu cực của few/a few và little/a little . Đồng thời, bài học mở rộng thêm các hạn định từ phổ biến như another, other, each, every, both cùng quy tắc sắp xếp thứ tự hạn định từ chuẩn xác trong câu.", 7, createdAt },
                    { 14, 1, "Prepositions (Giới từ)", "Chuyên đề này giúp bạn làm chủ các cách dùng nâng cao và linh hoạt hơn của giới từ trong tiếng Anh. Bạn sẽ phân biệt được sự thay đổi sắc thái ý nghĩa khi giới từ đi kèm với tính từ và động từ quen thuộc. Đồng thời, các cặp giới từ chỉ thời gian dễ gây nhầm lẫn như by/until, during/for hay in time/on time cũng sẽ được làm rõ chi tiết.", 8, createdAt },
                    { 15, 1, "Conjunctions (Liên từ)", "Chuyên mục \"Conjunctions (Liên từ)\" giúp bạn nâng cao kỹ năng kết nối các ý tưởng phức tạp, giúp văn viết và nói trở nên mạch lạc hơn. Bạn sẽ nắm vững cách dùng liên từ tương quan để đảm bảo cấu trúc song song và sự hòa hợp ngữ pháp trong câu. Bên cạnh đó, bài học cũng khai thác sâu các liên từ phụ thuộc diễn đạt sự tương phản, lý do, thời gian và điều kiện để tối ưu hóa khả năng diễn đạt của bạn.", 9, createdAt },
                    { 16, 2, "Present Tenses (Các thì hiện tại)", "Chuyên mục này giúp bạn nâng cao kỹ năng sử dụng các thì hiện tại thông qua việc phân biệt chuyên sâu giữa động từ trạng thái và động từ hành động, cũng như các cách dùng nâng cao của thì hiện tại đơn và hiện tại tiếp diễn. Bên cạnh đó, bạn sẽ làm chủ thì hiện tại hoàn thành (đơn và tiếp diễn) trong tương quan so sánh với quá khứ đơn cùng các từ đi kèm dễ lẫn lộn như just, already, yet, been/gone . Đây là bước đệm quan trọng giúp bạn diễn đạt linh hoạt, chính xác và tự nhiên hơn trong cả giao tiếp lẫn các bài thi tiếng Anh.", 1, createdAt },
                    { 17, 2, "Time expressions (Trạng từ và cụm chỉ thời gian)", "Nhóm bài học này cung cấp kiến thức toàn diện về các trạng từ và cụm từ chỉ thời gian phổ biến trong tiếng Anh. Bạn sẽ nắm vững cách xác định các mốc thời gian trong quá khứ, diễn tả khoảng thời gian kéo dài cũng như thiết lập các thời hạn cụ thể. Bên cạnh đó, các trạng từ quen thuộc như already, yet, still, recently hay no longer cũng được hướng dẫn chi tiết giúp bạn diễn đạt câu một cách mượt mà và chính xác.", 2, createdAt },
                    { 18, 2, "Past Tenses (Các thì quá khứ)", "Nhóm bài học này giúp bạn làm chủ các thì quá khứ để diễn tả và kể lại chuỗi sự kiện trong quá khứ một cách tự nhiên, sinh động. Bạn sẽ hiểu rõ cách kết hợp linh hoạt giữa quá khứ đơn, tiếp diễn và hoàn thành để mô tả bối cảnh, sự gián đoạn hay các hành động xảy ra trước một mốc thời gian. Bên cạnh đó, chuyên mục cũng giúp phân biệt quá khứ hoàn thành đơn với tiếp diễn và áp dụng thành thạo các cấu trúc diễn tả thói quen trong quá khứ như used to , would hay was always V-ing .", 3, createdAt },
                    { 19, 2, "Future Tenses (Các thì tương lai)", "Chuyên mục này cung cấp kiến thức nâng cao và toàn diện về các cấu trúc diễn tả tương lai trong tiếng Anh, giúp bạn phân biệt rõ ràng giữa \"will\", \"be going to\" và các thì hiện tại dùng cho kế hoạch hay lịch trình cố định. Bên cạnh việc làm chủ các mệnh đề chỉ thời gian và điều kiện, bạn còn được khám phá các thì tương lai tiếp diễn, tương lai hoàn thành cùng các cấu trúc trang trọng như \"be about to\" hay \"be due to\". Hãy làm chủ mọi sắc thái biểu đạt để tự tin lựa chọn dạng tương lai chuẩn xác và tự nhiên nhất trong từng ngữ cảnh giao tiếp!", 4, createdAt },
                    { 20, 2, "Future in the Past (Tương lai trong quá khứ)", "Nhóm ngữ pháp này giúp bạn nắm vững cách diễn đạt các hành động, kế hoạch hoặc dự định được nhìn nhận từ một thời điểm trong quá khứ. Thông qua các cấu trúc mở rộng như was/were going to , would và was/were about to , bạn sẽ biết cách diễn tả một sự việc sắp sửa xảy ra hoặc một dự đoán, lời hứa đã thực hiện trước đó. Việc làm chủ chủ đề này sẽ giúp bài nói và viết của bạn trở nên linh hoạt, giàu tính kể chuyện và tự nhiên hơn.", 5, createdAt },
                    { 21, 3, "Comparisons (So sánh)", "Chủ đề So sánh (Comparisons) cung cấp toàn bộ kiến thức nền tảng và nâng cao giúp bạn diễn tả chính xác sự tương quan giữa các đối tượng trong tiếng Anh. Bạn sẽ học từ các dạng cơ bản như so sánh bằng, so sánh hơn, so sánh nhất cho đến các trường hợp bất quy tắc, từ nhấn mạnh và cấu trúc so sánh số lượng. Bên cạnh đó, các mẫu câu so sánh kép, cách dùng mở rộng của so sánh nhất và sự khác biệt giữa \"like\", \"as\", \"than\" cũng được giải thích chi tiết nhằm giúp bạn giao tiếp tự nhiên và chuẩn xác.", 1, createdAt },
                    { 22, 3, "Conditional Sentences (Câu điều kiện)", "Câu điều kiện là cấu trúc ngữ pháp quan trọng dùng để diễn tả sự việc, hành động phụ thuộc vào một điều kiện nhất định. Chuyên mục này hệ thống đầy đủ các loại câu điều kiện từ cơ bản (loại 0, 1, 2, 3) đến các biến thể mở rộng, câu điều kiện hỗn hợp và cấu trúc đảo ngữ. Ngoài ra, bài học còn cung cấp các từ nối thay thế linh hoạt cùng các dạng giả định trang trọng, giúp bạn diễn đạt tiếng Anh tự nhiên và chính xác trong mọi ngữ cảnh.", 2, createdAt },
                    { 23, 3, "Wish clauses (Câu ước)", "Câu ước (Wish clauses) được dùng để diễn tả mong muốn về một điều không có thật, trái ngược với thực tế ở hiện tại, quá khứ hoặc mong muốn một sự thay đổi trong tương lai.", 3, createdAt },
                    { 24, 3, "Wish and unreal-past extras (Ước, as if, if only)", "Nhóm ngữ pháp này giúp bạn diễn đạt các mong muốn, giả định hoặc tình huống không có thực ở hiện tại và quá khứ. Thông qua các cấu trúc như If only , As if / As though và Would rather , bạn sẽ dễ dàng bộc lộ sự nuối tiếc cũng như các so sánh mang tính giả định. Việc nắm vững cách sử dụng thì quá khứ giả định (unreal past) sẽ giúp văn phong của bạn trở nên tinh tế và tự nhiên hơn.", 4, createdAt },
                    { 25, 3, "Passive voice (Câu bị động)", "Câu bị động (Passive voice) được sử dụng khi chúng ta muốn tập trung sự chú ý vào đối tượng chịu tác động của hành động, thay vì đối tượng thực hiện hành động đó.", 5, createdAt },
                    { 26, 3, "Passive voice extensions (Mở rộng bị động)", "Nhóm ngữ pháp \"Mở rộng bị động\" giúp bạn nâng cao khả năng sử dụng câu bị động một cách linh hoạt và tự nhiên trong nhiều ngữ cảnh phức tạp. Chuyên mục này cung cấp kiến thức toàn diện từ bị động ở các thì, dạng bị động với động từ khuyết thiếu, nguyên mẫu, V-ing cho đến bị động hai tân ngữ và cấu trúc \"Get-passive\". Bên cạnh đó, bạn sẽ làm chủ các dạng bị động tường thuật chuyên sâu cùng cấu trúc nhờ bảo (causative) để diễn đạt ý tưởng chuyên nghiệp và chuẩn xác hơn.", 6, createdAt },
                    { 27, 3, "Subjunctive and Imperative Moods (Thức giả định và mệnh lệnh)", "Nhóm ngữ pháp này tập trung vào hai thức quan trọng trong tiếng Anh dùng để thể hiện mong muốn, yêu cầu, giả định hoặc câu lệnh: Thức giả định (Subjunctive) và Thức mệnh lệnh (Imperative). Thức mệnh lệnh giúp bạn đưa ra các lời chỉ dẫn, yêu cầu trực tiếp một cách ngắn gọn và rõ ràng. Trong khi đó, thức giả định bao gồm các cấu trúc diễn tả tình huống không có thực, điều ước, cùng các dạng đặc biệt như \"were-subjunctive\" và các cụm từ cố định (formulaic subjunctive). Việc nắm vững nhóm kiến thức này sẽ giúp câu văn của bạn trở nên linh hoạt, tự nhiên và giàu sắc thái biểu cảm hơn.", 7, createdAt },
                    { 28, 3, "Reported speech (Câu tường thuật)", "Câu tường thuật (Reported speech) là điểm ngữ pháp quan trọng giúp bạn thuật lại lời nói, ý kiến hoặc câu hỏi của người khác một cách chính xác và tự nhiên. Chuyên mục này sẽ hướng dẫn chi tiết quy tắc lùi thì, biến đổi động từ khuyết thiếu và cách chuyển đổi từ câu trần thuật, câu hỏi đến các dạng câu mệnh lệnh hay lời khuyên. Ngoài ra, bạn cũng sẽ nắm vững các cấu trúc động từ tường thuật nâng cao và phân biệt rõ ràng cách sử dụng giữa \"say\", \"tell\" và \"ask\".", 8, createdAt },
                    { 29, 3, "Clauses (Mệnh đề)", "Mệnh đề (Clauses) là một trong những thành phần ngữ pháp cốt lõi giúp bạn mở rộng câu và truyền tải thông tin một cách mạch lạc, rõ ràng. Chuyên mục này tổng hợp đầy đủ các kiến thức từ cơ bản đến nâng cao về mệnh đề quan hệ (bao gồm dạng rút gọn, đại từ đi với giới từ), mệnh đề danh từ và đa dạng các mệnh đề trạng ngữ. Bên cạnh đó, bạn cũng sẽ được tìm hiểu cách kết hợp các mệnh đề để cấu tạo nên các kiểu câu từ đơn, câu ghép đến câu phức và câu phức-ghép. Việc làm chủ chuyên đề này sẽ giúp bạn nâng cao đáng kể kỹ năng diễn đạt tiếng Anh một cách linh hoạt và tự nhiên.", 9, createdAt },
                    { 30, 4, "Yes/No Questions (Câu hỏi Yes/No)", "Câu hỏi Yes/No là dạng câu hỏi cơ bản trong tiếng Anh dùng để xác nhận thông tin, yêu cầu người nghe trả lời bằng \"Yes\" hoặc \"No\". Chủ đề này sẽ hướng dẫn bạn cách đặt câu hỏi với động từ \"to be\", trợ động từ \"do/does/did\", động từ khuyết thiếu, động từ \"have\" và các thì tiếp diễn. Ngoài ra, bạn cũng sẽ nắm vững cách đưa ra câu trả lời ngắn chuẩn xác cũng như cách dùng ngữ điệu để biến một câu trần thuật thành câu hỏi.", 1, createdAt },
                    { 31, 4, "Wh-Questions (Câu hỏi có từ để hỏi)", "Câu hỏi có từ để hỏi (Wh-Questions) là dạng câu được sử dụng phổ biến nhằm thu thập thông tin chi tiết về người, sự vật, lý do hay cách thức trong tiếng Anh. Chuyên đề này sẽ hướng dẫn bạn chi tiết từ cấu trúc câu hỏi chủ ngữ, tân ngữ cơ bản đến cách kết hợp từ hỏi với danh từ, tính từ, trạng từ và giới từ đứng cuối. Bên cạnh đó, bạn cũng sẽ nắm vững các mẫu câu hỏi ý kiến, lý do nâng cao cùng những dạng câu hỏi nhấn mạnh và câu hỏi lặp (echo questions) để giao tiếp tự nhiên như người bản xứ.", 2, createdAt },
                    { 32, 4, "Choice Questions (Câu hỏi lựa chọn)", "Câu hỏi lựa chọn (Choice Questions) là dạng câu hỏi đưa ra các phương án cụ thể để người nghe cân nhắc và chọn ra câu trả lời phù hợp. Dạng cấu trúc này thường sử dụng liên từ \"or\" trong câu hỏi trực tiếp hoặc đi kèm với cụm từ \"whether... or not\" để thể hiện các khả năng trái ngược. Bên cạnh đó, bài học cũng hướng dẫn cách truyền đạt lại các lựa chọn này một cách chính xác thông qua dạng câu tường thuật (reported choice).", 3, createdAt },
                    { 33, 4, "Tag Questions (Câu hỏi đuôi)", "Câu hỏi đuôi (Tag Questions) là cấu trúc phổ biến trong tiếng Anh dùng để xác minh thông tin hoặc tìm kiếm sự đồng ý từ người nghe. Chuyên mục này sẽ hướng dẫn bạn từ các quy tắc cấu tạo cơ bản (khẳng định - phủ định), cách sử dụng ngữ điệu, đến các dạng đặc biệt với \"I am\", \"Let's\", câu mệnh lệnh và đại từ bất định. Ngoài ra, bạn cũng sẽ nắm vững cách kết hợp câu hỏi đuôi chính xác với trợ động từ \"have\", \"used to\", \"ought to\" cùng các động từ khuyết thiếu (modals).", 4, createdAt },
                    { 34, 4, "Negative Questions (Câu hỏi phủ định)", "Câu hỏi phủ định (Negative Questions) được sử dụng phổ biến trong tiếng Anh để xác nhận thông tin, thể hiện sự ngạc nhiên hoặc diễn đạt cảm xúc. Điểm quan trọng khi học chủ điểm này là nắm vững cấu trúc và tránh sự nhầm lẫn giữa \"Yes\" và \"No\" khi đưa ra câu trả lời. Ngoài ra, bạn cũng sẽ biết cách ứng dụng câu hỏi phủ định để đưa ra lời đề nghị hay lời mời một cách tự nhiên và lịch sự.", 5, createdAt },
                    { 35, 4, "Indirect Questions (Câu hỏi gián tiếp)", "Câu hỏi gián tiếp (Indirect Questions) là công cụ quan trọng giúp bạn diễn đạt thắc mắc và yêu cầu một cách lịch sự, trang nhã hơn trong giao tiếp tiếng Anh. Nhóm bài học này hướng dẫn chi tiết các dạng câu hỏi Wh- và Yes/No (với if/whether), cấu trúc lồng trong câu tường thuật, cùng dạng rút gọn \"Từ hỏi + to V\". Qua đó, bạn sẽ dễ dàng làm chủ các mẫu câu thắc mắc lịch sự, tinh tế và ứng dụng linh hoạt vào cả văn viết lẫn văn nói hàng ngày.", 6, createdAt },
                    { 36, 4, "Other question types and responses (Các dạng câu hỏi khác)", "Chủ đề này giúp bạn làm quen với các dạng câu hỏi đặc biệt và phản hồi tự nhiên trong giao tiếp tiếng Anh vượt ngoài các cấu trúc hỏi đáp thông thường. Bạn sẽ khám phá cách sử dụng câu hỏi tu từ để bộc lộ cảm xúc, câu hỏi lặp (echo questions) để thể hiện sự quan tâm, cùng các mẫu phản hồi ngắn thông dụng. Bên cạnh đó, phần tổng hợp trật tự từ và các lỗi thường gặp sẽ giúp bạn củng cố kiến thức để giao tiếp chính xác hơn.", 7, createdAt },
                    { 37, 5, "Expressing Preferences, Wants & Suggestions (Diễn đạt sở thích, mong muốn, gợi ý)", "Nhóm chủ đề này tổng hợp các cấu trúc ngữ pháp quan trọng giúp bạn thể hiện mong muốn, sở thích cá nhân cũng như đưa ra lời gợi ý, khuyên bảo hay yêu cầu một cách tự nhiên và lịch sự. Tại đây, bạn sẽ nắm vững cách sử dụng linh hoạt các mẫu câu phổ biến như Would like, Prefer, Suggest, Had better hay các cấu trúc sai khiến thường gặp. Việc làm chủ các dạng câu này sẽ giúp bạn nâng cao giao tiếp, tự tin ứng xử khéo léo trong cả đời sống hàng ngày lẫn môi trường công việc.", 1, createdAt },
                    { 38, 5, "Describing Feelings, Attitudes & Behaviors (Cảm xúc, thái độ, hành vi - gerund và infinitive)", "Nhóm ngữ pháp này tập trung vào cách sử dụng danh động từ (Gerund - V-ing) và động từ nguyên mẫu (To-Infinitive) để thể hiện chính xác cảm xúc, thái độ cũng như hành vi trong giao tiếp. Bạn sẽ nắm vững sự khác biệt giữa các động từ đi với V-ing, To-V, các trường hợp thay đổi ý nghĩa đặc biệt (như stop, regret, try, forget) cùng các cấu trúc với động từ tri giác và giới từ. Bên cạnh đó, bài học còn cung cấp các thành ngữ thông dụng chứa danh động từ giúp câu văn của bạn trở nên tự nhiên và linh hoạt hơn.", 2, createdAt },
                    { 39, 5, "Logical Connectors (Cause, Result, Contrast) - Liên từ chỉ nguyên nhân, kết quả, tương phản", "Nhóm từ nối logic (Logical Connectors) đóng vai trò then chốt trong việc liên kết các ý tưởng, giúp văn bản trở nên mạch lạc, chặt chẽ và tự nhiên hơn. Chuyên đề này tổng hợp toàn bộ các cấu trúc diễn đạt nguyên nhân - kết quả, sự tương phản, mục đích, bổ sung thông tin cho đến các dạng câu nhượng bộ và nhấn mạnh nâng cao. Việc làm chủ các liên từ này sẽ giúp bạn nâng tầm kỹ năng viết, giao tiếp cũng như bứt phá điểm số trong các bài thi tiếng Anh quan trọng.", 3, createdAt },
                    { 40, 5, "Time, Condition & Frequency (Thời gian, điều kiện, tần suất)", "Nhóm ngữ pháp này cung cấp các cấu trúc nền tảng giúp bạn diễn tả mối quan hệ thời gian, giả định điều kiện và thể hiện thói quen trong tiếng Anh. Thông qua các từ nối điều kiện, mệnh đề thời gian và các cấu trúc thông dụng như \"used to\" hay \"it takes\", bạn sẽ kết nối câu từ một cách linh hoạt. Việc làm chủ nhóm chủ điểm này sẽ giúp văn phong của bạn trở nên mạch lạc, tự nhiên và chính xác hơn.", 4, createdAt },
                    { 41, 5, "Other Common Patterns (Cấu trúc thông dụng khác)", "Nhóm bài học này tổng hợp các cấu trúc ngữ pháp thông dụng và vô cùng linh hoạt trong giao tiếp tiếng Anh hàng ngày. Bạn sẽ được làm quen với cách dùng \"Enough\" để chỉ mức độ, cấu trúc chủ ngữ giả \"It\", cùng các mẫu câu ngắn diễn đạt sự đồng tình như \"So do I\" hay \"Neither do I\". Việc nắm vững những mô hình này sẽ giúp câu văn của bạn trở nên tự nhiên, ngắn gọn và mượt mà hơn.", 5, createdAt },
                    { 42, 6, "Modality and modal perfect (Động từ khuyết thiếu và dạng hoàn thành)", "Nhóm chuyên đề này giúp bạn làm chủ toàn bộ cách dùng của các động từ khuyết thiếu từ cơ bản như diễn đạt khả năng, sự cho phép, nghĩa vụ cho đến thói quen trong quá khứ với used to và would . Bên cạnh đó, bạn sẽ nắm vững các mức độ phán đoán ở hiện tại cũng như cấu trúc dạng hoàn thành (Modal Perfect). Đây là nền tảng quan trọng giúp bạn đưa ra những suy đoán, lời trách móc hay sự tiếc nuối chính xác về các sự việc đã xảy ra trong quá khứ.", 1, createdAt },
                    { 43, 6, "Noun phrase: articles, determiners, quantity (Cụm danh từ)", "Cụm danh từ là thành phần ngữ pháp cốt lõi giúp xác định, miêu tả và làm rõ đối tượng được nhắc đến trong câu. Chuyên mục này cung cấp toàn bộ kiến thức quan trọng về mạo từ (a/an, the, zero article), từ chỉ định, sở hữu cách, cùng trật tự các từ hạn định và từ chỉ số lượng. Bên cạnh đó, bạn sẽ nắm vững cách phân biệt danh từ đếm được, không đếm được và các dạng danh từ số nhiều đặc biệt để diễn đạt tiếng Anh một cách chuẩn xác.", 2, createdAt },
                    { 44, 6, "Agreement and existential there (Hòa hợp và There is/are)", "Chủ đề ngữ pháp này giúp bạn nắm vững quy tắc hòa hợp giữa chủ ngữ và động từ – nền tảng cốt lõi để diễn đạt tiếng Anh chuẩn xác. Bạn sẽ học cách sử dụng thành thạo cấu trúc chỉ sự tồn tại \"There + be\" qua các thì, đồng thời làm quen với các quy tắc chia động từ cho cả chủ ngữ thông thường lẫn các trường hợp đặc biệt. Bên cạnh đó, bài học cũng giải thích chi tiết sự hòa hợp khi đi kèm với danh từ chỉ số lượng, phân số, khoảng cách và tiền bạc.", 3, createdAt },
                    { 45, 6, "Phrasal verbs and prepositions (Cụm động từ và giới từ đi kèm)", "Nhóm chủ đề này giúp bạn làm chủ cách sử dụng cụm động từ cùng các kết hợp giới từ phổ biến trong tiếng Anh. Người học sẽ lần lượt nắm vững các loại cụm động từ tách rời/không tách rời, cụm ba từ và cách phân loại theo tiểu từ (up, out, off, on, in). Bên cạnh đó, các cấu trúc cố định đi kèm giới từ của tính từ, động từ và danh từ cũng được tổng hợp đầy đủ nhằm nâng cao độ chính xác và tự nhiên trong giao tiếp.", 4, createdAt },
                    { 46, 6, "Word formation, collocation, punctuation (Cấu tạo từ, kết hợp từ, dấu câu)", "Nhóm bài học này giúp bạn nâng cao vốn từ vựng thông qua các quy tắc cấu tạo từ linh hoạt với tiền tố, hậu tố và từ ghép. Bên cạnh đó, bạn sẽ làm chủ các cụm từ kết hợp (collocations) tự nhiên giữa động từ, tính từ và trạng từ phổ biến trong tiếng Anh. Cuối cùng, các quy tắc sử dụng dấu câu chính xác sẽ hoàn thiện kỹ năng viết, giúp văn bản của bạn rõ ràng và chuyên nghiệp hơn.", 5, createdAt },
                    { 47, 6, "Advanced syntax: inversion, cleft, emphasis, ellipsis, participle clauses", "Chuyên mục cú pháp nâng cao giúp bạn làm chủ các cấu trúc câu linh hoạt và tinh tế, tạo điểm nhấn ấn tượng cho cả văn viết học thuật lẫn giao tiếp tự nhiên. Tại đây, bạn sẽ khám phá các kỹ thuật đảo ngữ, câu chẻ (cleft sentences), các phương thức nhấn mạnh, lược từ (ellipsis) và thế từ để tối ưu hóa độ súc tích của câu. Bên cạnh đó, việc nắm vững mệnh đề phân từ, cấu trúc tuyệt đối cùng nghệ thuật sắp xếp trật tự câu (fronting, extraposition) sẽ nâng tầm văn phong của bạn lên chuẩn bản ngữ.", 6, createdAt },
                    { 48, 6, "Discourse, cohesion and register (Diễn ngôn, liên kết và văn phong)", "Nhóm chủ đề này giúp bạn làm chủ cách kết nối câu từ mượt mà và điều chỉnh văn phong phù hợp với từng ngữ cảnh giao tiếp. Bạn sẽ học cách sử dụng các từ đệm trong văn nói, công cụ liên kết trong văn viết và từ tham chiếu để tạo tính chặt chẽ cho diễn ngôn. Bên cạnh đó, việc ứng dụng kỹ thuật danh từ hóa, ngôn ngữ giảm nhẹ cùng cách phân biệt văn phong trang trọng và thân mật sẽ giúp bạn sử dụng tiếng Anh một cách tự nhiên và chuyên nghiệp hơn.", 7, createdAt }
                });
        }

